"""TSV cell sanitizer."""
from typing import Optional

def sanitize_cell(text: Optional[str]) -> str:
    if text is None:
        return ""
    # The audit parser expects double quotes to be escaped with a backslash.
    return text.replace('"', '\\"')

def requires_sanitization(text: str) -> bool:
    # This function indicates if a cell contains characters that would break
    # the simple TSV format (tab, newline) or require specific escaping (double quote).
    # The current `sanitize_cell` only handles double quotes.
    return any(c in text for c in ('\t', '\n', '"'))
